refused_program.body:
set -uo pipefail
upstream="{upstream_remote}/{upstream_branch}"
base="$(git merge-base HEAD "$upstream")" || exit 1
git fetch --quiet {upstream_remote} >/dev/null 2>&1 || true
if [ ! -f "$(git rev-parse --git-path MERGE_HEAD)" ]; then
  git merge --no-edit "$upstream" >/dev/null 2>&1 || true
fi
tmpdir="$(mktemp -d)"
trap 'rm -rf "$tmpdir"' EXIT
git diff --name-only --diff-filter=U -z | tr '\0' '\n' > "$tmpdir/conflicted"
while IFS= read -r path; do
  [ -n "$path" ] || continue
  git show "$upstream:$path" > "$tmpdir/upstream" 2>/dev/null || continue
  git diff -U3 "$base" HEAD -- "$path" > "$tmpdir/local.diff" 2>/dev/null || true
  awk -v difffile="$tmpdir/local.diff" -v upfile="$tmpdir/upstream" '
    FILENAME == difffile {
      if ($0 ~ /^@@/) { in_hunk = 1; anchor = ""; anchor_ok = 0; next }
      if (!in_hunk) next
      c = substr($0, 1, 1)
      if (c == " ") { anchor = substr($0, 2); anchor_ok = 1; next }
      if (c == "-") { anchor_ok = 0; next }
      if (c == "+") {
        if (anchor_ok) { n++; A[n] = anchor; T[n] = substr($0, 2) }
        next
      }
      next
    }
    FILENAME == upfile { m++; U[m] = $0 }
    END {
      for (i = 1; i <= n; i++) {
        text = T[i]
        present = 0
        for (j = 1; j <= m; j++) if (U[j] == text) { present = 1; break }
        if (present) continue
        if (A[i] in lastpos) {
          pos = lastpos[A[i]]
        } else {
          pos = 0
          for (j = 1; j <= m; j++) if (U[j] == A[i]) { pos = j; break }
        }
        if (pos <= 0) {
          m++; U[m] = text; lastpos[A[i]] = m
        } else {
          for (j = m; j > pos; j--) U[j + 1] = U[j]
          U[pos + 1] = text
          m++
          lastpos[A[i]] = pos + 1
        }
      }
      for (i = 1; i <= m; i++) print U[i]
    }
  ' "$tmpdir/local.diff" "$tmpdir/upstream" > "$tmpdir/resolved"
  cat "$tmpdir/resolved" > "$path"
  git add -- "$path"
done < "$tmpdir/conflicted"
if [ -f "$(git rev-parse --git-path MERGE_HEAD)" ]; then
  git commit --no-edit --no-verify
fi
